#!/bin/sh
# Downloads every Higgsfield placeholder still and the hero loop into public/media.
# Run it on your Mac from the project folder:  sh scripts/fetch-media.sh
# (The build sandbox cannot reach Higgsfield's CDN, so this step runs on your machine.)
# Then add NEXT_PUBLIC_LOCAL_MEDIA=1 to .env.local so next/image serves optimised local files.
set -e
cd "$(dirname "$0")/../public/media"
get() { if [ -s "$1" ]; then echo "✓ $1"; else echo "→ $1"; curl -fL --retry 3 -o "$1" "$2"; fi; }
